import base64
import os

_THUMBNAILS_B64 = """"""

def main():
    target_dir = os.path.join("ArtistMusic", "helpers")
    os.makedirs(target_dir, exist_ok=True)
    target_path = os.path.join(target_dir, "_thumbnails.py")

    data = base64.b64decode(_THUMBNAILS_B64)
    with open(target_path, "wb") as f:
        f.write(data)

    print(f"Written: {target_path} ({len(data)} bytes)")

if __name__ == "__main__":
    main()
